 /**
diff --git a/code/frontier_solution/core_connect.h b/code/frontier_solution/core_connect.h
new file mode 100644
index 0000000..8864684
--- /dev/null
+++ b/code/frontier_solution/core_connect.h
@@ -0,0 +1,691 @@
+// Exact core-cell connectivity for grid-based DBSCAN.
+//
+// Core cells (grid cells holding at least one core point) arrive sorted
+// lexicographically by the retained grid builder.  Two core points within
+// epsilon lie in cells whose offsets satisfy sum_i max(|d_i| - 1, 0)^2 <= dim;
+// the non-strict bound also covers rounding in the retained cell assignment.
+// Every candidate cell pair c < c2 is examined in exactly one phase:
+//   face : one coordinate differs by one.  Adding e_l preserves the
+//          lexicographic order, so these pairs come from a linear merge of the
+//          sorted cell sequence with its shifted copy.
+//   near : every |d_i| <= 1 and at least two offsets are non-zero.
+//   far  : some |d_i| >= 2.
+// Near and far candidates are enumerated with a coordinate trie over the core
+// cells.  Before each of these phases every trie node records the component
+// shared by all cells in its subtree; a subtree in the querying cell's own
+// component is skipped as a whole, and once a single component remains no
+// candidate pair can cross components.
+//
+// Point distance tests use the retained arithmetic: the in-order sum of
+// squared coordinate differences compared with eps * eps.
+#ifndef FRONTIER_SOLUTION_CORE_CONNECT_H
+#define FRONTIER_SOLUTION_CORE_CONNECT_H
+
+#include <stdint.h>
+#include <stdlib.h>
+#include <string.h>
+#include <limits.h>
+#include <algorithm>
+#ifdef _OPENMP
+#include <omp.h>
+#endif
+
+#ifndef FS_SEQ_CELLS
+#define FS_SEQ_CELLS 48     // fewer core cells: run on the calling thread
+#endif
+#ifndef FS_LITE_FRAG
+#define FS_LITE_FRAG 4      // lite round when components > cells / FS_LITE_FRAG
+#endif
+#ifndef FS_LITE_CAP
+#define FS_LITE_CAP 32      // trie nodes visited per cell in the lite round
+#endif
+
+namespace fsol {
+
+typedef int32_t cidx;
+
+// ---------------------------------------------------------------------------
+// Concurrent union-find: roots are linked toward the smaller index, so every
+// parent pointer is <= its own index and a root is its component's minimum.
+static inline cidx ufFind(cidx *par, cidx x) {
+  for (;;) {
+    cidx p = __atomic_load_n(&par[x], __ATOMIC_RELAXED);
+    if (p == x) return x;
+    cidx gp = __atomic_load_n(&par[p], __ATOMIC_RELAXED);
+    if (gp == p) return p;
+    __atomic_store_n(&par[x], gp, __ATOMIC_RELAXED);
+    x = gp;
+  }
+}
+
+static inline void ufUnite(cidx *par, cidx a, cidx b) {
+  for (;;) {
+    a = ufFind(par, a);
+    b = ufFind(par, b);
+    if (a == b) return;
+    if (a < b) std::swap(a, b);
+    cidx expect = a;
+    if (__atomic_compare_exchange_n(&par[a], &expect, b, false,
+                                    __ATOMIC_RELAXED, __ATOMIC_RELAXED))
+      return;
+  }
+}
+
+// ---------------------------------------------------------------------------
+struct CoreConnect {
+  int dim;
+  double e2;
+  long minPts;
+  Grids *G;
+  intT *cm;
+  const double *base;   // point coordinates in input order
+
+  cidx m;               // number of core cells
+  GdLongDataType *cg;   // grid id of each core cell
+  PtLongDataType *cst;  // first point offset (grid order) of each core cell
+  cidx *cnum;           // number of points of each core cell
+  long *crd;            // cell coordinates [m * dim]
+  uint64_t *key;        // order-preserving packed coordinates, or NULL
+  uint64_t inc[64];     // key increment of +1 in coordinate l
+  long kmax[64];        // largest coordinate the key field l admits
+  double *rep;          // first core point of each cell [m * dim]
+  cidx *par;            // union-find over core cells
+  cidx *rootOf;         // root snapshot per cell
+  long *tcnt;           // per-thread counters
+  long roots;           // components at the last snapshot
+
+  // trie: level l has nNode[l] nodes sorted by prefix; node k has coordinate
+  // val[l][k] and (l < dim-1) children [ch[l][k], ch[l][k+1]) on level l+1.
+  // Level dim-1 nodes are the cells themselves; uni[l][k] is the subtree's
+  // common component or -1 (uni[dim-1] aliases rootOf).
+  long **val;
+  cidx **ch;
+  cidx **uni;
+  cidx *nNode;
+  unsigned char *fd;    // first coordinate where cell c differs from cell c-1
+  char *trieMem;
+
+  double *box;          // lazily computed core-point boxes [m * 2 * dim]
+  int *boxState;        // 0 absent, 1 being written, 2 ready
+
+  inline const long *X(cidx c) const { return crd + (long)c * dim; }
+  inline bool allCore(cidx c) const { return cnum[c] >= minPts; }
+  inline const double *pt(PtLongDataType i) const { return base + (long)G->GetPt(i) * dim; }
+  inline bool isCorePt(cidx c, PtLongDataType i) const { return allCore(c) || cm[G->GetPt(i)] != 0; }
+
+  inline bool closePts(const double *a, const double *b) const {
+    double s = 0;
+    for (int d = 0; d < dim; ++d) { double t = a[d] - b[d]; s += t * t; }
+    return !(s > e2);
+  }
+
+  // Squared gap between point a and box [lo, hi], accumulated in dimension
+  // order.  Rounding is monotone, so it never exceeds the retained squared
+  // distance from a to any point inside the box.
+  inline bool nearBox(const double *a, const double *lo, const double *hi) const {
+    double s = 0;
+    for (int d = 0; d < dim; ++d) {
+      double t = 0;
+      if (a[d] < lo[d]) t = lo[d] - a[d];
+      else if (a[d] > hi[d]) t = a[d] - hi[d];
+      s += t * t;
+    }
+    return !(s > e2);
+  }
+
+  inline bool nearBoxBox(const double *b1, const double *b2) const {
+    double s = 0;
+    for (int d = 0; d < dim; ++d) {
+      double t = 0;
+      if (b1[dim + d] < b2[d]) t = b2[d] - b1[dim + d];
+      else if (b2[dim + d] < b1[d]) t = b1[d] - b2[dim + d];
+      s += t * t;
+    }
+    return !(s > e2);
+  }
+
+  // Core-point bounding box of cell c: lo at [0, dim), hi at [dim, 2*dim).
+  // Returns the shared cached copy when ready, otherwise fills tmp.
+  const double *cellBox(cidx c, double *tmp) {
+    int s = __atomic_load_n(&boxState[c], __ATOMIC_ACQUIRE);
+    double *cached = box + (long)c * 2 * dim;
+    if (s == 2) return cached;
+    for (int d = 0; d < dim; ++d) { tmp[d] = 1e308; tmp[dim + d] = -1e308; }
+    PtLongDataType i0 = cst[c], i1 = i0 + cnum[c];
+    for (PtLongDataType i = i0; i < i1; ++i) {
+      if (!isCorePt(c, i)) continue;
+      const double *p = pt(i);
+      for (int d = 0; d < dim; ++d) {
+        if (p[d] < tmp[d]) tmp[d] = p[d];
+        if (p[d] > tmp[dim + d]) tmp[dim + d] = p[d];
+      }
+    }
+    int expect = 0;
+    if (s == 0 && __atomic_compare_exchange_n(&boxState[c], &expect, 1, false,
+                                              __ATOMIC_ACQUIRE, __ATOMIC_RELAXED)) {
+      memcpy(cached, tmp, sizeof(double) * 2 * dim);
+      __atomic_store_n(&boxState[c], 2, __ATOMIC_RELEASE);
+    }
+    return tmp;
+  }
+
+  // Exhaustive check restricted to points near the other cell's box.
+  bool bcpFiltered(cidx c1, cidx c2, const double *b1, const double *b2) const {
+    long n1 = cnum[c1], n2 = cnum[c2];
+    long need = n1 + n2;
+    const double *stackBuf[need <= 2048 ? need : 1];
+    const double **A = need <= 2048 ? stackBuf : (const double **)malloc(sizeof(double *) * need);
+    const double **B = A + n1;
+    long na = 0, nb = 0;
+    bool found = false;
+    for (PtLongDataType i = cst[c1], e = cst[c1] + n1; i < e; ++i) {
+      if (!isCorePt(c1, i)) continue;
+      const double *p = pt(i);
+      if (nearBox(p, b2, b2 + dim)) A[na++] = p;
+    }
+    if (na) {
+      for (PtLongDataType i = cst[c2], e = cst[c2] + n2; i < e; ++i) {
+        if (!isCorePt(c2, i)) continue;
+        const double *p = pt(i);
+        if (nearBox(p, b1, b1 + dim)) B[nb++] = p;
+      }
+      for (long i = 0; i < na && !found; ++i)
+        for (long j = 0; j < nb; ++j)
+          if (closePts(A[i], B[j])) { found = true; break; }
+    }
+    if (A != stackBuf) free(A);
+    return found;
+  }
+
+  bool bcpBoxed(cidx c1, cidx c2) {
+    double t1[2 * dim], t2[2 * dim];
+    const double *b1 = cellBox(c1, t1), *b2 = cellBox(c2, t2);
+    if (!nearBoxBox(b1, b2)) return false;
+    return bcpFiltered(c1, c2, b1, b2);
+  }
+
+  // Adjacent cells: a short direct scan usually finds a close pair at once;
+  // otherwise fall back to the filtered exhaustive check.
+  bool bcpNear(cidx c1, cidx c2) {
+    int budget = 24;
+    PtLongDataType i0 = cst[c1], i1 = i0 + cnum[c1];
+    PtLongDataType j0 = cst[c2], j1 = j0 + cnum[c2];
+    for (PtLongDataType i = i0; i < i1; ++i) {
+      if (!isCorePt(c1, i)) continue;
+      const double *p = pt(i);
+      for (PtLongDataType j = j0; j < j1; ++j) {
+        if (!isCorePt(c2, j)) continue;
+        if (closePts(p, pt(j))) return true;
+        if (--budget == 0) return bcpBoxed(c1, c2);
+      }
+    }
+    return false;
+  }
+
+  inline bool tryNear(cidx c, cidx c2) {
+    if (ufFind(par, c) == ufFind(par, c2)) return false;
+    if (!closePts(rep + (long)c * dim, rep + (long)c2 * dim) && !bcpNear(c, c2)) return false;
+    ufUnite(par, c, c2);
+    return true;
+  }
+
+  inline void tryFar(cidx c, cidx c2) {
+    if (ufFind(par, c) == ufFind(par, c2)) return;
+    if (bcpBoxed(c, c2)) ufUnite(par, c, c2);
+  }
+
+  // ---- face phase -----------------------------------------------------------
+  // sign of (X(x) + e_l) - X(y) in lexicographic order
+  inline int cmpShift(cidx x, int l, cidx y) const {
+    const long *a = X(x), *b = X(y);
+    for (int k = 0; k < dim; ++k) {
+      long av = a[k] + (k == l);
+      if (av != b[k]) return av < b[k] ? -1 : 1;
+    }
+    return 0;
+  }
+
+  void faceRangeKey(cidx i0, cidx i1) {
+    cidx j[dim];
+    for (int l = 0; l < dim; ++l)
+      j[l] = (cidx)(std::lower_bound(key + i0 + 1, key + m, key[i0] + inc[l]) - key);
+    for (cidx i = i0; i < i1; ++i) {
+      const uint64_t ki = key[i];
+      for (int l = 0; l < dim; ++l) {
+        const uint64_t want = ki + inc[l];
+        cidx y = j[l];
+        while (y < m && key[y] < want) ++y;
+        j[l] = y;
+        if (y < m && key[y] == want) tryNear(i, y);
+      }
+    }
+  }
+
+  void faceRange(cidx i0, cidx i1) {
+    if (i0 >= i1) return;
+    if (key) { faceRangeKey(i0, i1); return; }
+    cidx j[dim];
+    for (int l = 0; l < dim; ++l) {  // first y >= X(i0) + e_l
+      cidx lo = i0 + 1, hi = m;
+      while (lo < hi) {
+        cidx mid = lo + (hi - lo) / 2;
+        if (cmpShift(i0, l, mid) > 0) lo = mid + 1; else hi = mid;
+      }
+      j[l] = lo;
+    }
+    for (cidx i = i0; i < i1; ++i) {
+      for (int l = 0; l < dim; ++l) {
+        cidx y = j[l];
+        int c = 1;
+        while (y < m && (c = cmpShift(i, l, y)) > 0) ++y;
+        j[l] = y;
+        if (y < m && c == 0) tryNear(i, y);
+      }
+    }
+  }
+
+  // ---- snapshots (call from every thread of the team) -----------------------
+  void countRoots(int t, int nt, cidx c0, cidx c1) {
+    long r = 0;
+    for (cidx i = c0; i < c1; ++i) { cidx p = ufFind(par, i); rootOf[i] = p; r += p == i; }
+    tcnt[t] = r;
+    #pragma omp barrier
+    #pragma omp single
+    {
+      long s = 0;
+      for (int i = 0; i < nt; ++i) s += tcnt[i];
+      roots = s;
+    }
+  }
+
+  // common component of node k's children (level l < dim-1)
+  inline void uniformNode(int l, cidx k) {
+    const cidx *u = uni[l + 1];
+    cidx j0 = ch[l][k], j1 = ch[l][k + 1];
+    cidx r = u[j0];
+    for (cidx j = j0 + 1; j < j1 && r >= 0; ++j) if (u[j] != r) r = -1;
+    uni[l][k] = r;
+  }
+
+  void uniformAll() {
+    for (int l = dim - 2; l >= 0; --l) {
+      #pragma omp for schedule(static)
+      for (cidx k = 0; k < nNode[l]; ++k) uniformNode(l, k);
+    }
+  }
+
+  // ---- trie (call from every thread of the team) ----------------------------
+  void buildTrie(int t, int nt, cidx c0, cidx c1) {
+    #pragma omp single
+    fd = newA(unsigned char, m + 1);
+    long *lc = tcnt + (long)t * (dim + 1);
+    for (int l = 0; l < dim; ++l) lc[l] = 0;
+    for (cidx c = c0; c < c1; ++c) {
+      int f = 0;
+      if (c > 0) {
+        const long *a = X(c - 1), *b = X(c);
+        while (f < dim - 1 && a[f] == b[f]) ++f;
+      }
+      fd[c] = (unsigned char)f;
+      lc[f]++;
+    }
+    for (int l = 1; l < dim; ++l) lc[l] += lc[l - 1];  // cells starting a level-l node
+    #pragma omp barrier
+    #pragma omp single
+    {
+      for (int l = 0; l < dim; ++l) {
+        long s = 0;
+        for (int i = 0; i < nt; ++i) { long v = tcnt[(long)i * (dim + 1) + l]; tcnt[(long)i * (dim + 1) + l] = s; s += v; }
+        nNode[l] = (cidx)s;
+      }
+      long bytes = 0;
+      for (int l = 0; l < dim; ++l) bytes += (long)(nNode[l] + 1) * (sizeof(long) + 2 * sizeof(cidx)) + 16;
+      trieMem = newA(char, bytes);
+      char *q = trieMem;
+      for (int l = 0; l < dim; ++l) {
+        val[l] = (long *)q; q += (long)(nNode[l] + 1) * sizeof(long);
+        ch[l] = (cidx *)q; q += (long)(nNode[l] + 1) * sizeof(cidx);
+        uni[l] = (cidx *)q; q += (long)(nNode[l] + 1) * sizeof(cidx);
+        q += (8 - ((uintptr_t)q & 7)) & 7;
+      }
+      uni[dim - 1] = rootOf;
+      for (int l = 0; l + 1 < dim; ++l) ch[l][nNode[l]] = nNode[l + 1];
+    }
+    cidx run[dim];
+    for (int l = 0; l < dim; ++l) run[l] = (cidx)lc[l];
+    for (cidx c = c0; c < c1; ++c) {
+      const long *x = X(c);
+      for (int l = fd[c]; l < dim; ++l) {
+        cidx k = run[l]++;
+        val[l][k] = x[l];
+        if (l < dim - 1) ch[l][k] = run[l + 1];
+      }
+    }
+    #pragma omp barrier
+    uniformAll();
+  }
+
+  // ---- lite round: stop at the first union or when the visit cap is hit -----
+  bool dfsLite(cidx c, cidx r, const long *x, int l, cidx k0, cidx k1, bool tight, int nz, int &cap) {
+    const long *v = val[l];
+    const cidx *u = uni[l];
+    long xl = x[l];
+    long lo = tight ? xl : xl - 1, hi = xl + 1;
+    cidx k = k0;
+    if (k1 - k0 > 8) k = (cidx)(std::lower_bound(v + k0, v + k1, lo) - v);
+    else while (k < k1 && v[k] < lo) ++k;
+    for (; k < k1 && v[k] <= hi; ++k) {
+      if (--cap < 0) return true;
+      if (u[k] == r) continue;
+      bool same = v[k] == xl;
+      int nz2 = nz + !same;
+      if (l == dim - 1) {
+        if (nz2 >= 2 && tryNear(c, k)) return true;
+      } else {
+        if (dfsLite(c, r, x, l + 1, ch[l][k], ch[l][k + 1], tight && same, nz2, cap)) return true;
+      }
+    }
+    return false;
+  }
+
+  // ---- near phase: all |d_l| <= 1, at least two non-zero ---------------------
+  void dfsNear(cidx c, cidx r, const long *x, int l, cidx k0, cidx k1, bool tight, int nz) {
+    const long *v = val[l];
+    const cidx *u = uni[l];
+    long xl = x[l];
+    long lo = tight ? xl : xl - 1, hi = xl + 1;
+    cidx k = k0;
+    if (k1 - k0 > 8) k = (cidx)(std::lower_bound(v + k0, v + k1, lo) - v);
+    else while (k < k1 && v[k] < lo) ++k;
+    for (; k < k1 && v[k] <= hi; ++k) {
+      if (u[k] == r) continue;
+      bool same = v[k] == xl;
+      int nz2 = nz + !same;
+      if (l == dim - 1) {
+        if (nz2 >= 2) tryNear(c, k);
+      } else {
+        dfsNear(c, r, x, l + 1, ch[l][k], ch[l][k + 1], tight && same, nz2);
+      }
+    }
+  }
+
+  // ---- far phase: 0 < sum max(|d_l|-1,0)^2 <= dim ---------------------------
+  void dfsFar(cidx c, cidx r, const long *x, int l, cidx k0, cidx k1,
+              long budget, bool tight, bool pen) {
+    const long *v = val[l];
+    const cidx *u = uni[l];
+    long xl = x[l];
+    long K = 1;
+    while (K * K <= budget) ++K;  // largest |d| with (|d|-1)^2 <= budget
+    long lo = tight ? xl : xl - K, hi = xl + K;
+    cidx k = k0;
+    if (k1 - k0 > 8) k = (cidx)(std::lower_bound(v + k0, v + k1, lo) - v);
+    else while (k < k1 && v[k] < lo) ++k;
+    for (; k < k1 && v[k] <= hi; ++k) {
+      if (u[k] == r) continue;
+      long dl = v[k] - xl; if (dl < 0) dl = -dl;
+      long p = dl > 1 ? (dl - 1) * (dl - 1) : 0;
+      if (p > budget) continue;
+      if (l == dim - 1) {
+        if (pen || p > 0) tryFar(c, k);
+      } else {
+        dfsFar(c, r, x, l + 1, ch[l][k], ch[l][k + 1], budget - p,
+               tight && v[k] == xl, pen || p > 0);
+      }
+    }
+  }
+
+  inline void liteCell(cidx c) {
+    int cap = FS_LITE_CAP;
+    dfsLite(c, rootOf[c], X(c), 0, 0, nNode[0], true, 0, cap);
+  }
+  inline void nearCell(cidx c) { dfsNear(c, rootOf[c], X(c), 0, 0, nNode[0], true, 0); }
+  inline void farCell(cidx c) { dfsFar(c, rootOf[c], X(c), 0, 0, nNode[0], dim, true, false); }
+};
+
+} // namespace fsol
+
+// ---------------------------------------------------------------------------
+// Few core cells: check every cell pair directly on the calling thread.
+static GdLongDataType *FsolClusterFew(fsol::CoreConnect &cc, GdLongDataType *ids, long n,
+                                      const GdLongDataType *cells, fsol::cidx m) {
+  using namespace fsol;
+  const int dim = cc.dim;
+  GdLongDataType cg[m + 1];
+  PtLongDataType cst[m + 1];
+  cidx cnum[m + 1], par[m + 1];
+  int boxState[m + 1];
+  long crd[(long)(m + 1) * dim];
+  double box[(long)(m + 1) * 2 * dim];
+  cc.m = m; cc.cg = cg; cc.cst = cst; cc.cnum = cnum; cc.par = par; cc.crd = crd;
+  cc.box = box; cc.boxState = boxState;
+  for (cidx k = 0; k < m; ++k) {
+    cg[k] = cells[k];
+    cst[k] = cc.G->GetStartOffset(cells[k]);
+    cnum[k] = (cidx)cc.G->GetNumPts(cells[k]);
+    par[k] = k;
+    boxState[k] = 0;
+    for (int l = 0; l < dim; ++l) crd[(long)k * dim + l] = cc.G->ReadGridVec(cells[k], l);
+  }
+  for (cidx a = 0; a < m; ++a) {
+    for (cidx b = a + 1; b < m; ++b) {
+      long pen = 0;
+      for (int l = 0; l < dim && pen <= dim; ++l) {
+        long dl = crd[(long)a * dim + l] - crd[(long)b * dim + l];
+        if (dl < 0) dl = -dl;
+        if (dl > 1) pen += (dl - 1) * (dl - 1);
+      }
+      if (pen > dim || ufFind(par, a) == ufFind(par, b)) continue;
+      if (pen == 0 ? cc.bcpNear(a, b) : cc.bcpBoxed(a, b)) ufUnite(par, a, b);
+    }
+  }
+  memset(ids, 0xff, sizeof(GdLongDataType) * n);
+  for (cidx k = 0; k < m; ++k) {
+    GdLongDataType lab = ufFind(par, k);
+    for (PtLongDataType a = cst[k], e = cst[k] + cnum[k]; a < e; ++a) {
+      PtLongDataType o = cc.G->GetPt(a);
+      if (cc.allCore(k) || cc.cm[o]) ids[o] = lab;
+    }
+  }
+  return ids;
+}
