+// ---------------------------------------------------------------------------
+static GdLongDataType *FsolClusterCore(_seq<pointNd> *t_points, DbscanParams *t_params,
+                                       Grids *t_grids, bool *isCoreGrid, intT *cm) {
+  using namespace fsol;
+  const int dim = t_points->A[0].m_dim;
+  const long n = t_points->n;
+  const GdLongDataType ng = t_grids->GetNumGrids();
+  GdLongDataType *ids = newA(GdLongDataType, n);
+
+  CoreConnect cc;
+  memset(&cc, 0, sizeof(cc));
+  cc.dim = dim;
+  cc.e2 = t_params->m_epsilon * t_params->m_epsilon;
+  cc.minPts = t_params->m_minPts;
+  cc.G = t_grids;
+  cc.cm = cm;
+  cc.base = t_points->A[0].m_data;
+  {
+    // scan for core cells eight flags at a time; stop once there are many
+    GdLongDataType few[FS_SEQ_CELLS];
+    cidx nf = 0;
+    GdLongDataType g = 0;
+    for (; g + 8 <= ng && nf < FS_SEQ_CELLS; g += 8) {
+      uint64_t w;
+      memcpy(&w, isCoreGrid + g, 8);
+      if (!w) continue;
+      for (int j = 0; j < 8 && nf < FS_SEQ_CELLS; ++j) if (isCoreGrid[g + j]) few[nf++] = g + j;
+    }
+    for (; g < ng && nf < FS_SEQ_CELLS; ++g) if (isCoreGrid[g]) few[nf++] = g;
+    if (nf < FS_SEQ_CELLS) return FsolClusterFew(cc, ids, n, few, nf);
+  }
+
+#ifdef _OPENMP
+  const int T = omp_get_max_threads();
+#else
+  const int T = 1;
+#endif
+  cc.tcnt = newA(long, (long)T * (dim + 1) + 1);
+  // packed keys: field l holds coordinates 0..numGrid[l] (the retained cell
+  // computation never exceeds it) and one more, so key + inc[l] never carries
+  bool keyOk = dim <= 64, keyBad = false;
+  {
+    const OtLongDataType *ndn = t_grids->GetNDNumGrids();
+    int sh = 0;
+    for (int l = dim - 1; l >= 0 && keyOk; --l) {
+      long mx = ndn[l] < 0 ? -1 : (long)ndn[l];
+      int w = 1;
+      while (w < 62 && (mx + 1) >> w) ++w;
+      keyOk = mx >= 0 && ((mx + 1) >> w) == 0 && sh + w <= 63;
+      cc.inc[l] = (uint64_t)1 << sh;
+      cc.kmax[l] = mx;
+      sh += w;
+    }
+  }
+  cc.val = newA(long *, dim);
+  cc.ch = newA(cidx *, dim);
+  cc.uni = newA(cidx *, dim);
+  cc.nNode = newA(cidx, dim);
+
+  #pragma omp parallel num_threads(T)
+  {
+#ifdef _OPENMP
+    const int t = omp_get_thread_num(), nt = omp_get_num_threads();
+#else
+    const int t = 0, nt = 1;
+#endif
+    // ---- compact core cells ---------------------------------------------
+    GdLongDataType g0 = ng * t / nt, g1 = ng * (t + 1) / nt;
+    {
+      long c = 0;
+      for (GdLongDataType g = g0; g < g1; ++g) c += isCoreGrid[g];
+      cc.tcnt[t] = c;
+    }
+    #pragma omp barrier
+    #pragma omp single
+    {
+      long s = 0;
+      for (int i = 0; i < nt; ++i) { long v = cc.tcnt[i]; cc.tcnt[i] = s; s += v; }
+      cidx m = (cidx)s;
+      cc.m = m;
+      cc.cg = newA(GdLongDataType, m + 1);
+      cc.cst = newA(PtLongDataType, m + 1);
+      cc.cnum = newA(cidx, m + 1);
+      cc.crd = newA(long, (long)(m + 1) * dim);
+      if (keyOk) cc.key = newA(uint64_t, m + 1);
+      cc.rep = newA(double, (long)(m + 1) * dim);
+      cc.par = newA(cidx, m + 1);
+      cc.rootOf = newA(cidx, m + 1);
+      cc.box = newA(double, (long)(m + 1) * 2 * dim);
+      cc.boxState = newA(int, m + 1);
+    }
+    {
+      long k = cc.tcnt[t];
+      for (GdLongDataType g = g0; g < g1; ++g) {
+        if (!isCoreGrid[g]) continue;
+        cc.cg[k] = g;
+        cc.cst[k] = t_grids->GetStartOffset(g);
+        cc.cnum[k] = (cidx)t_grids->GetNumPts(g);
+        long *x = cc.crd + k * dim;
+        for (int l = 0; l < dim; ++l) x[l] = t_grids->ReadGridVec(g, l);
+        if (keyOk) {
+          uint64_t kv = 0;
+          for (int l = 0; l < dim; ++l) {
+            kv += (uint64_t)x[l] * cc.inc[l];
+            if (x[l] < 0 || x[l] > cc.kmax[l]) __atomic_store_n(&keyBad, true, __ATOMIC_RELAXED);
+          }
+          cc.key[k] = kv;
+        }
+        PtLongDataType i = cc.cst[k];
+        if (!cc.allCore((cidx)k)) while (!cm[t_grids->GetPt(i)]) ++i;
+        memcpy(cc.rep + k * dim, cc.pt(i), sizeof(double) * dim);
+        cc.par[k] = (cidx)k;
+        cc.boxState[k] = 0;
+        ++k;
+      }
+    }
+    #pragma omp barrier
+    const cidx m = cc.m;
+    const cidx c0 = (cidx)((long)m * t / nt), c1 = (cidx)((long)m * (t + 1) / nt);
+    if (keyBad) {
+      #pragma omp barrier
+      #pragma omp single
+      { free(cc.key); cc.key = NULL; }
+    }
+
+    // ---- face phase -----------------------------------------------------
+    {
+      const cidx chunk = 256;
+      #pragma omp for schedule(dynamic, 1)
+      for (cidx q = 0; q < (m + chunk - 1) / chunk; ++q)
+        cc.faceRange(q * chunk, std::min(m, (cidx)(q * chunk + chunk)));
+    }
+    cc.countRoots(t, nt, c0, c1);
+
+    // ---- near and far phases (nothing left to check once one component remains)
+    if (cc.roots > 1) {
+      cc.buildTrie(t, nt, c0, c1);
+      if (cc.roots * FS_LITE_FRAG > m) {
+        // fragmented after face unions: a capped scan per cell that stops at
+        // the first union coarsens the components cheaply
+        #pragma omp for schedule(dynamic, 16)
+        for (cidx i = 0; i < m; ++i) cc.liteCell(i);
+        cc.countRoots(t, nt, c0, c1);
+        cc.uniformAll();
+      }
+    }
+    if (cc.roots > 1) {
+      #pragma omp for schedule(dynamic, 16)
+      for (cidx i = 0; i < m; ++i) cc.nearCell(i);
+      cc.countRoots(t, nt, c0, c1);
+    }
+    if (cc.roots > 1) {
+      cc.uniformAll();
+      #pragma omp for schedule(dynamic, 16)
+      for (cidx i = 0; i < m; ++i) cc.farCell(i);
+    }
+
+    // ---- labels: grids whose first point lies in this thread's share --------
+    {
+      PtLongDataType p0 = (PtLongDataType)(n * t / nt), p1 = (PtLongDataType)(n * (t + 1) / nt);
+      GdLongDataType a = 0, b = ng;
+      while (a < b) { GdLongDataType mid = a + (b - a) / 2; if (t_grids->GetStartOffset(mid) < p0) a = mid + 1; else b = mid; }
+      const GdLongDataType ga = a;
+      b = ng;
+      while (a < b) { GdLongDataType mid = a + (b - a) / 2; if (t_grids->GetStartOffset(mid) < p1) a = mid + 1; else b = mid; }
+      const GdLongDataType gb = a;
+      cidx k = (cidx)(std::lower_bound(cc.cg, cc.cg + m, ga) - cc.cg);
+      for (GdLongDataType g = ga; g < gb; ++g) {
+        PtLongDataType s = t_grids->GetStartOffset(g), e = s + t_grids->GetNumPts(g);
+        if (k < m && cc.cg[k] == g) {
+          GdLongDataType lab = ufFind(cc.par, k);
+          if (cc.allCore(k)) {
+            for (PtLongDataType i = s; i < e; ++i) ids[t_grids->GetPt(i)] = lab;
+          } else {
+            for (PtLongDataType i = s; i < e; ++i) {
+              PtLongDataType o = t_grids->GetPt(i);
+              ids[o] = cm[o] ? lab : -1;
+            }
+          }
+          ++k;
+        } else {
+          for (PtLongDataType i = s; i < e; ++i) ids[t_grids->GetPt(i)] = -1;
+        }
+      }
+    }
+  }
+  free(cc.tcnt); free(cc.val); free(cc.ch); free(cc.uni); free(cc.nNode);
+  free(cc.trieMem); free(cc.fd);
+  free(cc.cg); free(cc.cst); free(cc.cnum); free(cc.crd); free(cc.key); free(cc.rep); free(cc.par); free(cc.rootOf);
+  free(cc.box); free(cc.boxState);
+  return ids;
+}
